/**
 * Walks every comment on one issue. `includeArchived` is set when the caller
 * needs deleted rows too (dropping an archived issue's whole thread from the
 * index). Pages are followed so a long thread is not truncated at 100.
 */
async function forEachComment(
  orgId: OrgId,
  issueId: IssueId,
  includeArchived: boolean,
  visit: (comment: Comment) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  for (;;) {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived,
      limit: INDEX_PAGE_SIZE,
      cursor,
    });
    for (const comment of page.items) {
      await visit(comment);
    }
    if (page.nextCursor === null) return;
    cursor = page.nextCursor;
  }
}

