/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import { isLive } from "@/lib/soft-delete";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/**
 * Rows read per page while walking the org's content. Repository pages are
 * capped at this size and ordered newest-first, so every cursor must be
 * followed or the oldest issues and comments never get indexed.
 */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Replaces one tenant's index with exactly its live content: live projects,
 * non-archived issues, and non-deleted comments on those issues (a live reply
 * whose parent was deleted is still live). Nothing from any other workspace
 * is read or removed. Clearing this org's documents first makes a second run
 * replace the same set instead of inserting duplicates, and drops anything
 * the index still held for archived issues or deleted comments.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteSearchDocumentsForOrg(orgId);

    await eachPage(
      (cursor) =>
        projectRepo.listProjects({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: false,
        }),
      async (project) => {
        if (!isLive(project)) return;
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await eachPage(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: false,
        }),
      async (issue) => {
        if (!isLive(issue)) return;

        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
          return;
        }

        await eachPage(
          (cursor) =>
            commentRepo.listComments({
              orgId,
              issueId: issue.id,
              includeArchived: false,
              limit: PAGE_SIZE,
              cursor,
            }),
          async (comment) => {
            // Deleted parents stay out; a live reply under one is its own row.
            if (!isLive(comment)) return;
            try {
              await indexComment(orgId, comment);
              result.processed += 1;
            } catch (error) {
              result.failed += 1;
              logger.error("failed to index comment", {
                commentId: comment.id,
                reason: error instanceof Error ? error.message : String(error),
              });
            }
          },
        );
      },
    );
  });
}

async function eachPage<T>(
  load: (cursor: string | null) => Promise<{
    items: readonly T[];
    nextCursor: string | null;
  }>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  for (;;) {
    const page = await load(cursor);
    for (const item of page.items) {
      await visit(item);
    }
    if (page.nextCursor === null) return;
    cursor = page.nextCursor;
  }
}

