/**
 * Temporary verification for comment counts and search index maintenance.
 * Not part of the project suite.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/rate-limit", async () => {
  const { rateLimitModule } = await import(
    "/private/tmp/bench-scratch/8b2ecffd-205d-41df-98d4-9e73412686be/tests/server/_support/doubles/misc"
  );
  return rateLimitModule;
});

import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as searchRepo from "@/server/repositories/search-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "/private/tmp/bench-scratch/8b2ecffd-205d-41df-98d4-9e73412686be/tests/server/_support/fixtures";
import type { Tenant } from "/private/tmp/bench-scratch/8b2ecffd-205d-41df-98d4-9e73412686be/tests/server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("reindex-check", "growth");
  other = await createTenant("reindex-other", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

async function hits(org: Tenant, q: string, kinds: Array<"issue" | "comment" | "project">) {
  const page = await searchService.search(org.actors.member, {
    orgId: org.org.id,
    q,
    kinds,
    limit: 25,
    cursor: null,
  });
  return page.total;
}

describe("search maintenance", () => {
  it("counts only live comments, including replies", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Count carrier" }),
    );
    const parent = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Parent to delete",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Live reply",
      parentId: parent.id,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Sibling",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: parent.id,
    });

    const loaded = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(loaded.commentCount).toBe(2);
  });

  it("drops only the deleted comment from search", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "IssueStaysMarker" }),
    );
    const parent = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "DeleteMeMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ReplyStaysMarker",
      parentId: parent.id,
      mentionedUserIds: [],
    });

    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: parent.id,
    });

    expect(await hits(tenant, "DeleteMeMarker", ["comment"])).toBe(0);
    expect(await hits(tenant, "ReplyStaysMarker", ["comment"])).toBe(1);
    expect(await hits(tenant, "IssueStaysMarker", ["issue"])).toBe(1);
  });

  it("drops every comment of an archived issue and nothing else", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ArchiveIssueMarker" }),
    );
    const parent = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ArchiveCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ArchiveReplyMarker",
      parentId: parent.id,
      mentionedUserIds: [],
    });

    const otherIssue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "OtherIssueMarker" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: otherIssue.id,
      body: "OtherCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });

    const foreign = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "ForeignIssueMarker" }),
    );
    await commentService.createComment(other.actors.member, {
      orgId: other.org.id,
      issueId: foreign.id,
      body: "ForeignCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    expect(await hits(tenant, "ArchiveIssueMarker", ["issue"])).toBe(0);
    expect(await hits(tenant, "ArchiveCommentMarker", ["comment"])).toBe(0);
    expect(await hits(tenant, "ArchiveReplyMarker", ["comment"])).toBe(0);
    expect(await hits(tenant, "OtherIssueMarker", ["issue"])).toBe(1);
    expect(await hits(tenant, "OtherCommentMarker", ["comment"])).toBe(1);
    expect(await hits(other, "ForeignIssueMarker", ["issue"])).toBe(1);
    expect(await hits(other, "ForeignCommentMarker", ["comment"])).toBe(1);
    expect(await hits(tenant, "ForeignIssueMarker", ["issue"])).toBe(0);
  });

  it("rebuilds exactly the live content, including pages past 100, without duplicates", async () => {
    const issueIds: string[] = [];
    for (let i = 0; i < 105; i += 1) {
      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: `BulkIssueMarker-${i}` }),
      );
      issueIds.push(issue.id);
    }

    const threadIssue = issueIds[0]!;
    for (let i = 0; i < 105; i += 1) {
      await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: threadIssue as never,
        body: `BulkCommentMarker-${i}`,
        parentId: null,
        mentionedUserIds: [],
      });
    }

    const parent = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: threadIssue as never,
      body: "DeletedParentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: threadIssue as never,
      body: "LiveReplyMarker",
      parentId: parent.id,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: parent.id,
    });

    const doomed = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "DoomedIssueMarker" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doomed.id,
      body: "DoomedCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, doomed.id);

    // Drift: put the archived issue back as if the index were stale.
    await searchService.indexIssue(tenant.org.id, {
      ...(await import("@/server/repositories/issue-repository")).findIssueById
        ? (await (await import("@/server/repositories/issue-repository")).findIssueById(tenant.org.id, doomed.id))!
        : doomed,
    });

    const { runSearchReindexJob } = await import("@/server/jobs/search-reindex-job");
    await runSearchReindexJob(tenant.org.id);
    const once = await searchRepo.countIndexed(tenant.org.id);
    await runSearchReindexJob(tenant.org.id);
    const twice = await searchRepo.countIndexed(tenant.org.id);

    expect(twice).toBe(once);
    expect(await hits(tenant, "BulkIssueMarker-0", ["issue"])).toBe(1);
    expect(await hits(tenant, "BulkIssueMarker-104", ["issue"])).toBe(1);
    expect(await hits(tenant, "BulkCommentMarker-0", ["comment"])).toBe(1);
    expect(await hits(tenant, "BulkCommentMarker-104", ["comment"])).toBe(1);
    expect(await hits(tenant, "DeletedParentMarker", ["comment"])).toBe(0);
    expect(await hits(tenant, "LiveReplyMarker", ["comment"])).toBe(1);
    expect(await hits(tenant, "DoomedIssueMarker", ["issue"])).toBe(0);
    expect(await hits(tenant, "DoomedCommentMarker", ["comment"])).toBe(0);
    expect(await hits(tenant, "OtherIssueMarker", ["issue"])).toBe(1);
    expect(await hits(tenant, "OtherCommentMarker", ["comment"])).toBe(1);
    expect(await hits(other, "ForeignIssueMarker", ["issue"])).toBe(1);
    expect(await hits(other, "ForeignCommentMarker", ["comment"])).toBe(1);
    expect(await hits(tenant, "ForeignIssueMarker", ["issue"])).toBe(0);
  });
});

